    'eb769605-5e2c-4175-8b9d-e3864ceaafb1'::uuid,
    'b735b3be-4a7d-59d4-b897-1dbbd886a516'::uuid,
    'apple_music',
    'ris-backfill-v1',
    '6d3a004a1d1a6e98cd0dba4b0c510fba86e530836e17fd16ffa5080db6a1cc2f',
    'ris_lab_plaintext_v1',
    'cmlzLWxhYjogbm8ga21zIG9uIHRoaXMgbGFuZQ==',
    'arn:aws:kms:ris-lab:000000000000:key/no-kms-on-this-lane',
    '[{"scope_key": "apple_music:recently_played:recently_played", "source_code": "apple_music", "data_type": "recently_played", "action_type": "recently_played", "snapshot_mode": "full_snapshot", "completeness": "partial"}, {"scope_key": "apple_music:recommendation:recommendation", "source_code": "apple_music", "data_type": "recommendation", "action_type": "recommendation", "snapshot_mode": "full_snapshot", "completeness": "partial"}]'::jsonb,
